// Build standup kickoff messages for each agent
const agents = [
  { id: 'main', delay: 0 },
  { id: 'eng', delay: 2000 },
  { id: 'research', delay: 4000 },
  { id: 'finance', delay: 6000 },
  { id: 'ops', delay: 8000 },
  { id: 'infosec', delay: 10000 }
];

const date = new Date().toLocaleDateString('en-CA');
const messages = agents.map(a => ({
  agentId: a.id,
  message: `MORNING STANDUP ${date}: Write your status to workspace/ops/agent-status/${a.id}.json with fields: sprintGoal, workingOn, completedYesterday, ETA, blockers. Keep it brief — OPS will compile at 8:15am.`,
  delay: a.delay
}));

return messages.map(m => ({ json: m }));
